import{_ as i,o as s,c as n,a3 as a}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"New-Player Progression and Precautions: Wuling","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"萌新入坑流程及注意事项「武陵篇」","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=L0hsh88XqUwFigit3JjUTg","scope":"page"}},"headers":[],"relativePath":"src/page-L0hsh88XqUwFigit3JjUTg.md","filePath":"logistics/src/page-L0hsh88XqUwFigit3JjUTg.md","lastUpdated":null}'),t={name:"src/page-L0hsh88XqUwFigit3JjUTg.md"};function o(r,e,l,c,g,d){return s(),n("div",null,[...e[0]||(e[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="萌新入坑流程及注意事项「武陵篇」" aria-hidden="true"></span><h1 id="new-player-progression-and-precautions-wuling" tabindex="-1">New-Player Progression and Precautions: Wuling <a class="header-anchor" href="#new-player-progression-and-precautions-wuling" aria-label="Permalink to &quot;New-Player Progression and Precautions: Wuling&quot;">​</a></h1><blockquote><p>Source page ID: <code>L0hsh88XqUwFigit3JjUTg</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=L0hsh88XqUwFigit3JjUTg" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-grey"><em>Before reading: players rushing progression and players taking their time have vastly different experiences in Wuling. Rushing requires very tight scheduling and resource allocation; relaxed play has little pressure and will not be discussed in detail. This guide helps players rushing progression plan their route and use resources sensibly.</em></span></p><p><span id="source-block-8umcWj3tmbjudi7FUj2RZm"></span></p><span class="logistics-source-anchor" id="第零阶段-进入武陵前的预备知识" aria-hidden="true"></span><h3 id="stage-zero-what-to-know-before-entering-wuling" tabindex="-1">Stage Zero: What to Know Before Entering Wuling <a class="header-anchor" href="#stage-zero-what-to-know-before-entering-wuling" aria-label="Permalink to &quot;Stage Zero: What to Know Before Entering Wuling&quot;">​</a></h3><p>1.After creating an account and entering the game, follow the fixed opening story and tutorial. Once events unlock, accept the special “Main Story Early Unlock: Wuling” event mission to enter Wuling directly.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6141527773096cad.q90-531f0ac7ce0f246c.webp" alt="New-Player Progression and Precautions: Wuling"></p><p>2.Wuling&#39;s main-story route is Jingyu Valley → Wuling City → Qingbo Stockade → Marker Stone → Yinglung Pass → North Wuling Exclusion Zone → Si&#39;s Painting. The other areas are side-story maps.</p><p>3.Every blueprint in this guide needs water connected. Connections for water, Precipitation Acid, Inergen and Xiragen are marked with Control Ports in obvious locations. Unless specifically stated otherwise, each Control Port corresponds to one water/Precipitation Acid pump. The blueprints include many safeguards; modifying them on your own is not recommended.</p><p>4.Collect as many survey posts as possible while doing missions to accumulate Industry Points. If points are tight, unlock exactly what each stage&#39;s diagram shows. Otherwise, even after placing a blueprint you may be unable to use it, and some facilities&#39; output settings may even be disrupted!</p><p>5.Stock Bills are extremely tight early on. Spend every bit where it counts—on the blade&#39;s edge, not its back, handle or sheath!</p><p>6.The diagram shows mission progress, construction level, mineral output and precautions at each milestone for players rushing progression. Every blueprint here matches the minimum mineral output at its stage, so mineral demand will not exceed supply.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8d0766297bd93b67.png" alt="New-Player Progression and Precautions: Wuling"></p><p><span id="source-block-zyNrWvjZ8IZLxWcFn70ZSH"></span></p><span class="logistics-source-anchor" id="第一阶段-主线推完武陵城-解锁武陵基地-天王坪据点" aria-hidden="true"></span><h3 id="stage-one-finish-wuling-city-s-main-story-unlock-wuling-base-and-sky-king-flats-outpost" tabindex="-1">Stage One: Finish Wuling City&#39;s Main Story (Unlock Wuling Base and Sky King Flats Outpost) <a class="header-anchor" href="#stage-one-finish-wuling-city-s-main-story-unlock-wuling-base-and-sky-king-flats-outpost" aria-label="Permalink to &quot;Stage One: Finish Wuling City&#39;s Main Story (Unlock Wuling Base and Sky King Flats Outpost)&quot;">​</a></h3><p>Connect all mining spots in Jingyu Valley and Wuling City, reaching 250/min Originium Ore and 60/min Ferrium Ore, with construction level 2. Pick up the required plants around the base; only 1 of each is needed. Unlock the 5 items shown in the Industry Points diagram. A mission unlocks the environmental monitoring station without spending Stock Bills and gives a photography assignment: your first payout of 12500 Stock Bills! Use it to unlock Wuling City Base&#39;s depot bus. Place the first blueprint there and connect its Control Ports to two water pumps for the initial startup.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a66295804b10cfd6.q90-d4558e8f7a7f4071.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d56ea7202db7d7b0.q90-f3d02e419094ef2f.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-3d27564d0b8bf07b.jpeg" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-641556f0a417ab57.q90-c90335cc16ca6678.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><span class="mark-blue">[Stage 1 – Wuling] EF011I96i065iU2O34O7</span></p><p>The blueprint consumes 180/min Originium Ore and 60/min Ferrium Ore. The depot initially needs only one Yazhen and one Sandleaf. During startup, approximately 325 Yazhen, 325 Sandleaf, 3250 Ferrium Parts and 3250 Xiranite accumulate in the depot. Once stable, it produces 6/min LC Wuling Batteries and 3/min Yazhen Syringes [C], with normal total power generation of 1800.</p><p>Then continue the missions…</p><p><span id="source-block-vMNBmjr3Ce6UXxKUoVtfzH"></span></p><span class="logistics-source-anchor" id="第二阶段-主线推完首墩-解锁首墩据点" aria-hidden="true"></span><h3 id="stage-two-finish-marker-stone-s-main-story-unlock-marker-stone-outpost" tabindex="-1">Stage Two: Finish Marker Stone&#39;s Main Story (Unlock Marker Stone Outpost) <a class="header-anchor" href="#stage-two-finish-marker-stone-s-main-story-unlock-marker-stone-outpost" aria-label="Permalink to &quot;Stage Two: Finish Marker Stone&#39;s Main Story (Unlock Marker Stone Outpost)&quot;">​</a></h3><p>Fully connect the mining spots, remembering the new spots that appear in Wuling City and Jingyu Valley. Reach 360/min Originium Ore, 90/min Ferrium Ore and 120/min Cuprium Ore, with construction level 5. Unlock the 4 items shown in the Industry Points diagram. Expand Wuling Base&#39;s area once and add one Depot Bus Section. Ways to obtain the required Stock Bills, from easiest to hardest:</p><ol><li>Unlocking an outpost immediately gives it a Stock Bill reserve at half its cap. Exchange batteries/medicine to collect it.</li><li>Besides the environmental monitoring assignment provided by the main story, Wuling has another worth 54000 Stock Bills. Take a photo at the specified location.</li><li>The storage node at Wuling&#39;s lower right costs 12500 Stock Bills to unlock and offers 3 orders worth 110000+ Stock Bills each. This is time-consuming and laborious, so it is not recommended.</li></ol><p><img src="/endfield-skydoc/logistics/src/assets/images/img-2ebedb155b0aed65.q90-1b737e24f6675274.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-df1dc00b84c258d1.q90-ad1f8ce3b68eed29.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-6632b360e621d9d0.q90-5a6e4f8465ba67b9.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-d5ce7e193670fef3.q90-3600efa888bdd011.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><span class="mark-blue">[Stage 2 – Wuling A] EF01081a76aE7i18E179</span></p><p><span class="mark-blue">[Stage 2 – Wuling B] EF01i1UA57Ao52e872U4</span></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a2e7bb59d2dcafc2.q90-f6688770f1f4da4d.webp" alt="New-Player Progression and Precautions: Wuling"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-e8e871669ce59409.q90-ec03ed451f7a0dab.webp" alt="New-Player Progression and Precautions: Wuling"></p><p>Select the first blueprint and move it to the base&#39;s upper left. Join Stage 2 A underneath and Stage 2 B at the upper right, then reconnect 6 water pumps. After startup, 3250 Cuprium Parts accumulate. Once stable, the line provides 9 LC Wuling Batteries, 6 Yazhen Syringes [A] and 4.5 Yazhen Syringes [C] per minute, with normal power generation of 3400 (minor fluctuations do not affect production). This meets Stock Bill exchange requirements until all three outposts reach level 2.</p><p><em>Stage 2 is an incremental blueprint that fits into Stage 1, drawing from or filling parts of that line. Make sure the Stage 1 blueprint is complete and has not been modified!</em></p></div>',1)])])}const h=i(t,[["render",o]]);export{u as __pageData,h as default};
